const TOOLS = {
  lookupOrder: ["orderId"],
  refund: ["orderId", "amount", "reason"],
};

function isPlainObject(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isValidToolCall(call) {
  if (!isPlainObject(call) || typeof call.name !== "string") return false;
  const allowed = TOOLS[call.name];
  if (allowed === undefined) return false;
  const args = call.arguments;
  if (!isPlainObject(args)) return false;
  const keys = Object.keys(args);
  if (keys.length !== allowed.length) return false;
  for (const key of keys) {
    if (!allowed.includes(key)) return false;
  }
  if (typeof args.orderId !== "string" || args.orderId.length === 0) return false;
  if (call.name === "lookupOrder") return true;
  return (
    Number.isInteger(args.amount) &&
    args.amount >= 1 &&
    args.amount <= 500 &&
    typeof args.reason === "string" &&
    args.reason.length >= 3 &&
    args.reason.length <= 200
  );
}
